function variantIndex(salt){let x=((state.runSeed||1)^(Math.imul((salt|0)+1,0x45d9f3b)))>>>0;x=Math.imul(x^(x>>>16),0x45d9f3b);x=Math.imul(x^(x>>>16),0x45d9f3b);x=(x^(x>>>16))>>>0;return x}
function ensureMetrics(){state.metrics=state.metrics||{trust:55,quality:52,reliability:58,wellbeing:70,health:92,attendance:100,conflict:0};for(const[k,v]of Object.entries({trust:55,quality:52,reliability:58,wellbeing:70,health:92,attendance:100,conflict:0}))if(!Number.isFinite(state.metrics[k]))state.metrics[k]=v;return state.metrics}
function bounded(v){return Math.max(0,Math.min(100,Math.round(v)))}
function applyRank(rank){let m=ensureMetrics();if(rank>=3){m.quality+=2;m.reliability+=1;m.trust+=1}else if(rank>=1){m.quality+=1;m.reliability+=1}else if(rank===0){m.quality-=2;m.reliability-=1;m.trust-=1;m.wellbeing-=1}else{m.quality-=4;m.reliability-=4;m.trust-=4;m.wellbeing-=2;m.conflict+=3}for(const k of Object.keys(m))m[k]=bounded(m[k]);if(getFatigue()>=80){m.quality=bounded(m.quality-1);m.wellbeing=bounded(m.wellbeing-1)}}
function shuffleChoiceRows(options,extra,salt){let rows=options.map((option,source)=>({option,source}));if(extra)rows.push({option:extra,source:-1});for(let i=rows.length-1;i>0;i--){let j=variantIndex(salt+i*97)%(i+1);[rows[i],rows[j]]=[rows[j],rows[i]]}return rows}
function variant(axis,salt){let list=variationAxes[axis];return list[variantIndex(salt)%list.length]}
function makeDialoguePack(salt){let person=variant('people',salt+13);return{opener:variant('openers',salt+1),person,pressure:variant('pressures',salt+37),light:variant('light',salt+71),coach:variant('coaches',salt+109)}}
