function category(j){let t=(j.role+' '+j.description+' '+j.spec).toLowerCase();for(const k of ['dev','design','marketing','analyst','test','support'])if(keywords[k].some(w=>t.includes(w)))return k;return 'general'}
function matchJob(j){let t=(j.role+' '+j.description+' '+j.spec).toLowerCase(),text=(state.profile.skills||'').toLowerCase()+' '+(state.profile.major||'').toLowerCase()+' '+(state.profile.about||'').toLowerCase()+' '+(state.profile.cvText||'').toLowerCase();let words=[...new Set(text.split(/[\s,./;|]+/).filter(x=>x.length>2))];let hits=words.filter(w=>t.includes(w)).length;let cat=category(j), cvText=(state.profile.cvText||'').toLowerCase(),interest=(state.profile.interest||'').toLowerCase();let catScore=(interest===cat?18:0);let exp=keywords[cat]||[];let skillScore=exp.filter(w=>text.includes(w)).length*7,cvSkillScore=exp.filter(w=>cvText.includes(w)).length*9;return Math.min(98,42+hits*7+skillScore+cvSkillScore+catScore+(j.spec?4:0))}
function sceneForEvent(month,index){let cat=category(state.selected||{role:''});let routes={dev:['coding_lab','server_room','interview','meeting','demo_stage','handoff'],design:['studio','research_room','interview','field_test','demo_stage','office'],marketing:['content_studio','interview','field_event','cafeteria','presentation','office'],analyst:['data_room','interview','meeting','research_room','presentation','handoff'],test:['qa_lab','server_room','interview','meeting','demo_stage','handoff'],support:['service_desk','interview','field_visit','office','presentation','cafeteria'],general:['office','interview','studio','field_visit','demo_stage','handoff']};let route=routes[cat]||routes.general;return route[(month*2+index*3+state.jobIndex+(state.runSeed%route.length))%route.length]}
