function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">AI CAREER LIFE SIMULATOR</div><h1>ฝึกงานครั้งนี้<br>จะพาคุณไป<em>ไกลแค่ไหน?</em></h1><p>จำลองเส้นทางสหกิจศึกษา 10 เดือน ตั้งแต่ส่งใบสมัครจนถึงวันสุดท้ายในบริษัท มีเหตุการณ์ 20 เรื่องต่อเดือนและทบทวนผลงานทุกเดือน · ควรเผื่อเวลาเล่นประมาณ 1 ชั่วโมงขึ้นไป · ทุกการตัดสินใจมีผลสะสม</p><p class="path-hint">เริ่มจากดูตำแหน่งงาน เลือกเส้นทางของคุณ แล้วค่อยค้นพบว่าเรื่องนี้จะพาไปจบแบบไหน</p><button class="primary" onclick="go('profile')">เริ่มต้นชีวิตฝึกงาน <span>→</span></button><p class="fine">ทุกตัวละครเป็น AI จำลอง · โปรไฟล์เก็บในอุปกรณ์นี้</p><p class="notice">${SIM_NOTICE}</p></div><div class="pixel-card"><canvas id="heroart"></canvas><div class="caption"><span>PROCEDURAL PIXEL WORLD</span><span>YOUR STORY · YOUR PIXEL WORLD</span></div></div></section>`;pixel($('#heroart'),'office',Math.random()*99999,true)}
